contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 setVal, uint256 newVal) public {
        uint256 beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        bool setReverted;
        c.SetMinSum(setVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setReverted = true;
        } else {
            setReverted = false;
        }
        uint256 afterSetMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(newVal); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        uint256 afterSecondMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!secondReverted || afterSecondMinSum == afterSetMinSum);
    }
}

