pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 setVal, uint256 newVal) internal {
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        bool setReverted;
        try c.SetMinSum(setVal) {
            setReverted = false;
        } catch {
            setReverted = true;
        }
        uint256 afterSetMinSum;
        try c.MinSum() returns (uint256 __r) { afterSetMinSum = __r; } catch { return; }
        bool secondReverted;
        try c.SetMinSum(newVal) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 afterSecondMinSum;
        try c.MinSum() returns (uint256 __r) { afterSecondMinSum = __r; } catch { return; }
        assertTrue(!secondReverted || afterSecondMinSum == afterSetMinSum);
    }

    function testFuzz_run(uint256 setVal, uint256 newVal) public {
        _run(setVal, newVal);
    }

    receive() external payable {}
}
